	ContentType?: string;
	ContentLength?: number;
	ETag?: string;
	LastModified?: Date;
	CacheControl?: string;
	Metadata?: Record<string, string>;
}) {
	return {
		contentType: value.ContentType,
		contentLength: value.ContentLength,
		etag: value.ETag,
		lastModified: value.LastModified,
